CREATE TYPE public.app_role AS ENUM ('buyer','supplier','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL CHECK(length(full_name) BETWEEN 1 AND 100), phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30), city text NOT NULL DEFAULT '' CHECK(length(city)<=100), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.business_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, business_name text NOT NULL CHECK(length(business_name) BETWEEN 1 AND 150), business_type text NOT NULL DEFAULT '' CHECK(length(business_type)<=100), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.business_profiles TO authenticated; GRANT ALL ON public.business_profiles TO service_role; ALTER TABLE public.business_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY business_read ON public.business_profiles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY business_update ON public.business_profiles FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.supplier_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, company_name text NOT NULL CHECK(length(company_name) BETWEEN 1 AND 150), description text NOT NULL DEFAULT '' CHECK(length(description)<=2000), city text NOT NULL DEFAULT '' CHECK(length(city)<=100), verification_status text NOT NULL DEFAULT 'pending' CHECK(verification_status IN ('pending','approved','rejected')), is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(user_id IS NOT NULL OR is_demo));
GRANT SELECT ON public.supplier_profiles TO anon; GRANT SELECT,UPDATE ON public.supplier_profiles TO authenticated; GRANT ALL ON public.supplier_profiles TO service_role; ALTER TABLE public.supplier_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY supplier_read ON public.supplier_profiles FOR SELECT USING(verification_status='approved' OR user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY supplier_update ON public.supplier_profiles FOR UPDATE TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.guard_supplier_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') AND (NEW.verification_status IS DISTINCT FROM OLD.verification_status OR NEW.is_demo IS DISTINCT FROM OLD.is_demo OR NEW.user_id IS DISTINCT FROM OLD.user_id) THEN RAISE EXCEPTION 'Only administrators may change verification or ownership'; END IF; RETURN NEW; END $$;
CREATE TRIGGER supplier_verification_guard BEFORE UPDATE ON public.supplier_profiles FOR EACH ROW EXECUTE FUNCTION public.guard_supplier_verification();
CREATE FUNCTION public.handle_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE chosen public.app_role; BEGIN chosen := CASE WHEN NEW.raw_user_meta_data->>'account_type'='supplier' THEN 'supplier'::public.app_role ELSE 'buyer'::public.app_role END; INSERT INTO public.profiles(id,full_name,phone,city) VALUES(NEW.id,coalesce(nullif(trim(NEW.raw_user_meta_data->>'full_name'),''),'Account'),coalesce(NEW.raw_user_meta_data->>'phone',''),coalesce(NEW.raw_user_meta_data->>'city','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,chosen); INSERT INTO public.business_profiles(user_id,business_name,business_type) VALUES(NEW.id,coalesce(nullif(trim(NEW.raw_user_meta_data->>'business_name'),''),'Business'),coalesce(NEW.raw_user_meta_data->>'business_type','')); IF chosen='supplier' THEN INSERT INTO public.supplier_profiles(user_id,company_name,city,description) VALUES(NEW.id,coalesce(nullif(trim(NEW.raw_user_meta_data->>'business_name'),''),'Company'),coalesce(NEW.raw_user_meta_data->>'city',''),coalesce(NEW.raw_user_meta_data->>'description','')); END IF; RETURN NEW; END $$;
CREATE TRIGGER greenswitch_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_signup();
CREATE TABLE public.product_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK(length(slug)<=80), name_en text NOT NULL CHECK(length(name_en)<=100), name_ar text NOT NULL CHECK(length(name_ar)<=100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.product_categories TO anon,authenticated; GRANT ALL ON public.product_categories TO service_role; ALTER TABLE public.product_categories ENABLE ROW LEVEL SECURITY; CREATE POLICY category_read ON public.product_categories FOR SELECT USING(true);
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES public.supplier_profiles(id) ON DELETE CASCADE, category_id uuid REFERENCES public.product_categories(id), name_en text NOT NULL CHECK(length(name_en) BETWEEN 1 AND 150), name_ar text NOT NULL DEFAULT '' CHECK(length(name_ar)<=150), description_en text NOT NULL DEFAULT '' CHECK(length(description_en)<=4000), description_ar text NOT NULL DEFAULT '' CHECK(length(description_ar)<=4000), category_slug text NOT NULL DEFAULT 'other', material text NOT NULL DEFAULT 'kraft', price numeric(12,2) NOT NULL CHECK(price>=0), moq integer NOT NULL DEFAULT 1 CHECK(moq>0), stock integer NOT NULL DEFAULT 0 CHECK(stock>=0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','published','rejected')), is_demo boolean NOT NULL DEFAULT false, sizes text[] NOT NULL DEFAULT '{}', specs jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.owns_supplier(sid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.supplier_profiles WHERE id=sid AND user_id=auth.uid()) $$;
CREATE FUNCTION public.public_product(pid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.products p JOIN public.supplier_profiles s ON s.id=p.supplier_id WHERE p.id=pid AND p.status='published' AND s.verification_status='approved' AND NOT p.is_demo AND NOT s.is_demo) $$;
CREATE POLICY product_read ON public.products FOR SELECT USING(public.public_product(id) OR public.owns_supplier(supplier_id) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY product_insert ON public.products FOR INSERT TO authenticated WITH CHECK(public.owns_supplier(supplier_id) AND status IN ('draft','pending') AND NOT is_demo);
CREATE POLICY product_update ON public.products FOR UPDATE TO authenticated USING(public.owns_supplier(supplier_id) OR public.has_role(auth.uid(),'admin')) WITH CHECK(public.owns_supplier(supplier_id) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY product_delete ON public.products FOR DELETE TO authenticated USING(public.owns_supplier(supplier_id) OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.guard_product_review() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN IF NEW.supplier_id IS DISTINCT FROM OLD.supplier_id OR NEW.is_demo IS DISTINCT FROM OLD.is_demo OR (NEW.status IN ('published','rejected') AND NEW.status IS DISTINCT FROM OLD.status) THEN RAISE EXCEPTION 'Only administrators may publish products or change ownership'; END IF; IF OLD.status='published' AND (NEW.name_en,NEW.name_ar,NEW.description_en,NEW.description_ar,NEW.material) IS DISTINCT FROM (OLD.name_en,OLD.name_ar,OLD.description_en,OLD.description_ar,OLD.material) THEN NEW.status='pending'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER product_review_guard BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.guard_product_review();
CREATE TABLE public.product_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, url text NOT NULL CHECK(length(url)<=2000 AND url ~ '^https://'), position integer NOT NULL DEFAULT 0 CHECK(position>=0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.product_images TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_images TO authenticated; GRANT ALL ON public.product_images TO service_role; ALTER TABLE public.product_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY image_read ON public.product_images FOR SELECT USING(public.public_product(product_id) OR EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND public.owns_supplier(p.supplier_id)) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY image_write ON public.product_images FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND public.owns_supplier(p.supplier_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND public.owns_supplier(p.supplier_id)));
CREATE TABLE public.product_sustainability_attributes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, attribute text NOT NULL CHECK(attribute IN ('compostable','recyclable','reusable','plastic-free','food-safe','local')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id,attribute));
GRANT SELECT ON public.product_sustainability_attributes TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_sustainability_attributes TO authenticated; GRANT ALL ON public.product_sustainability_attributes TO service_role; ALTER TABLE public.product_sustainability_attributes ENABLE ROW LEVEL SECURITY;
CREATE POLICY attribute_read ON public.product_sustainability_attributes FOR SELECT USING(public.public_product(product_id) OR EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND public.owns_supplier(p.supplier_id)) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY attribute_write ON public.product_sustainability_attributes FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND public.owns_supplier(p.supplier_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND public.owns_supplier(p.supplier_id)));
CREATE TABLE public.supplier_verification_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES public.supplier_profiles(id) ON DELETE CASCADE, storage_path text NOT NULL CHECK(length(storage_path)<=1000), file_name text NOT NULL CHECK(length(file_name)<=255), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.supplier_verification_documents TO authenticated; GRANT ALL ON public.supplier_verification_documents TO service_role; ALTER TABLE public.supplier_verification_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY document_read ON public.supplier_verification_documents FOR SELECT TO authenticated USING(public.owns_supplier(supplier_id) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY document_insert ON public.supplier_verification_documents FOR INSERT TO authenticated WITH CHECK(public.owns_supplier(supplier_id) AND split_part(storage_path,'/',1)=auth.uid()::text);
CREATE POLICY document_delete ON public.supplier_verification_documents FOR DELETE TO authenticated USING(public.owns_supplier(supplier_id));
CREATE POLICY verification_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='verification-documents' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY verification_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='verification-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'supplier'));
CREATE POLICY verification_file_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='verification-documents' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE TABLE public.saved_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,product_id));
GRANT SELECT,INSERT,DELETE ON public.saved_products TO authenticated; GRANT ALL ON public.saved_products TO service_role; ALTER TABLE public.saved_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY saved_own ON public.saved_products FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'buyer'));
CREATE TABLE public.shopping_carts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.shopping_carts TO authenticated; GRANT ALL ON public.shopping_carts TO service_role; ALTER TABLE public.shopping_carts ENABLE ROW LEVEL SECURITY; CREATE POLICY cart_own ON public.shopping_carts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'buyer'));
CREATE TABLE public.cart_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cart_id uuid NOT NULL REFERENCES public.shopping_carts(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, quantity integer NOT NULL CHECK(quantity>0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cart_id,product_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cart_items TO authenticated; GRANT ALL ON public.cart_items TO service_role; ALTER TABLE public.cart_items ENABLE ROW LEVEL SECURITY; CREATE POLICY cart_item_own ON public.cart_items FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.shopping_carts c WHERE c.id=cart_id AND c.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.shopping_carts c WHERE c.id=cart_id AND c.user_id=auth.uid()) AND public.public_product(product_id));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), buyer_id uuid NOT NULL REFERENCES public.profiles(id), supplier_id uuid NOT NULL REFERENCES public.supplier_profiles(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','shipped','completed','cancelled')), total numeric(12,2) NOT NULL CHECK(total>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY order_read ON public.orders FOR SELECT TO authenticated USING(buyer_id=auth.uid() OR public.owns_supplier(supplier_id) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id), quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(12,2) NOT NULL CHECK(unit_price>=0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.order_items TO authenticated; GRANT ALL ON public.order_items TO service_role; ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY; CREATE POLICY order_item_read ON public.order_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id));
CREATE TABLE public.group_buying_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES public.supplier_profiles(id), product_id uuid NOT NULL REFERENCES public.products(id), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 150), target_quantity integer NOT NULL CHECK(target_quantity>0), unit_price numeric(12,2) NOT NULL CHECK(unit_price>0), closes_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','open','closed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.group_buying_campaigns TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.group_buying_campaigns TO authenticated; GRANT ALL ON public.group_buying_campaigns TO service_role; ALTER TABLE public.group_buying_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY campaign_read ON public.group_buying_campaigns FOR SELECT USING((status='open' AND public.public_product(product_id)) OR public.owns_supplier(supplier_id) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY campaign_own ON public.group_buying_campaigns FOR ALL TO authenticated USING(public.owns_supplier(supplier_id)) WITH CHECK(public.owns_supplier(supplier_id) AND EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND p.supplier_id=group_buying_campaigns.supplier_id));
CREATE TABLE public.group_buying_participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES public.group_buying_campaigns(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id), quantity integer NOT NULL CHECK(quantity>0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(campaign_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.group_buying_participants TO authenticated; GRANT ALL ON public.group_buying_participants TO service_role; ALTER TABLE public.group_buying_participants ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_read ON public.group_buying_participants FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.group_buying_campaigns c WHERE c.id=campaign_id AND public.owns_supplier(c.supplier_id)));
CREATE POLICY participant_insert ON public.group_buying_participants FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'buyer') AND EXISTS(SELECT 1 FROM public.group_buying_campaigns c WHERE c.id=campaign_id AND c.status='open' AND c.closes_at>now()));
CREATE TABLE public.ai_recommendation_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, request text NOT NULL CHECK(length(request)<=4000), recommendations jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_recommendation_history TO authenticated; GRANT ALL ON public.ai_recommendation_history TO service_role; ALTER TABLE public.ai_recommendation_history ENABLE ROW LEVEL SECURITY; CREATE POLICY recommendation_own ON public.ai_recommendation_history FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.environmental_impact_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), order_id uuid REFERENCES public.orders(id), plastic_avoided_g numeric NOT NULL CHECK(plastic_avoided_g>=0), items_replaced integer NOT NULL CHECK(items_replaced>=0), methodology text NOT NULL CHECK(length(methodology)<=2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.environmental_impact_records TO authenticated; GRANT ALL ON public.environmental_impact_records TO service_role; ALTER TABLE public.environmental_impact_records ENABLE ROW LEVEL SECURITY; CREATE POLICY impact_read ON public.environmental_impact_records FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.supplier_verification_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES public.supplier_profiles(id), admin_id uuid NOT NULL REFERENCES public.profiles(id), decision text NOT NULL CHECK(decision IN ('approved','rejected','pending')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.supplier_verification_history TO authenticated; GRANT ALL ON public.supplier_verification_history TO service_role; ALTER TABLE public.supplier_verification_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY verification_history_read ON public.supplier_verification_history FOR SELECT TO authenticated USING(public.owns_supplier(supplier_id) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY verification_history_insert ON public.supplier_verification_history FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND admin_id=auth.uid());
CREATE FUNCTION public.admin_set_role(target uuid, chosen public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(target,chosen) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.admin_set_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.admin_set_role(uuid,public.app_role) TO authenticated;
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER touch_profile BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER touch_business BEFORE UPDATE ON public.business_profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER touch_supplier BEFORE UPDATE ON public.supplier_profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER touch_product BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE INDEX products_supplier_idx ON public.products(supplier_id); CREATE INDEX products_status_idx ON public.products(status); CREATE INDEX orders_buyer_idx ON public.orders(buyer_id); CREATE INDEX orders_supplier_idx ON public.orders(supplier_id); CREATE INDEX documents_supplier_idx ON public.supplier_verification_documents(supplier_id);